import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { Check } from 'lucide-react';

const PLANS = {
  starter: {
    name: 'Starter',
    price: 29,
    features: ['1 site', 'GEO Score', '7 dias de histórico']
  },
  pro: {
    name: 'Pro',
    price: 79,
    features: ['5 sites', 'GEO Score + Social Score', '90 dias de histórico', 'Relatórios em PDF']
  },
  agencia: {
    name: 'Agência',
    price: 199,
    features: ['Ilimitado', 'Tudo do Pro', 'Comparação com concorrentes', 'Monitoramento 24/7', 'API/Webhooks']
  }
};

export default function PlanSelection({ user, setSubscription }) {
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSelectPlan = async (planKey) => {
    setSelectedPlan(planKey);
    setLoading(true);
    try {
      const token = localStorage.getItem('authToken');
      const res = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/payment/create-subscription`,
        { plan: planKey },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setSubscription(res.data.subscription);
      navigate('/dashboard');
    } catch (e) {
      alert('Erro ao selecionar plano');
      setSelectedPlan(null);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="plan-selection">
      <div className="plan-header">
        <h1>Escolha seu plano</h1>
        <p>Selecione o plano que melhor atende suas necessidades</p>
      </div>
      <div className="plans-grid">
        {Object.entries(PLANS).map(([key, plan]) => (
          <div key={key} className={`plan-card ${selectedPlan === key ? 'selected' : ''}`}>
            <h2>{plan.name}</h2>
            <div className="price">R$ {plan.price}<span>/mês</span></div>
            <ul className="features">
              {plan.features.map((feature, idx) => (
                <li key={idx}>
                  <Check size={20} />
                  {feature}
                </li>
              ))}
            </ul>
            <button
              onClick={() => handleSelectPlan(key)}
              disabled={loading && selectedPlan === key}
              className="select-btn"
            >
              {loading && selectedPlan === key ? 'Ativando...' : 'Escolher'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
